package com.zomiggy.exception; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<?> validation(MethodArgumentNotValidException e){Map<String,String> errors=new HashMap<>();e.getBindingResult().getFieldErrors().forEach(x->errors.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("success",false,"message","Validation failed","errors",errors));} @ExceptionHandler({IllegalArgumentException.class,NoSuchElementException.class}) ResponseEntity<?> client(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("success",false,"message",e.getMessage()));} @ExceptionHandler(Exception.class) ResponseEntity<?> server(){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("success",false,"message","Unexpected server error"));} }